-- STEP 01 of 05 -- run on BOTH servers (Node A, then Node B).
-- Finish this step on both servers before starting step 02.
--
-- Creates the site-wide activity log (Site Tracking, phase 1): one `visit`
-- row per browser session and one `site_event` row per thing that happens
-- on the public site, written by POST /api/activity
-- (server/src/routes/activity.js).
--
-- Schema only: pglogical doesn't replicate it, so each server needs it.
-- Safe to re-run.
--
-- Both tables are INSERT-only, like counter_tracking / unmatched_path_hit,
-- with primary keys generated by the visitor's browser (UUIDs), so the two
-- servers can never write the same row and a resent batch is a no-op.

CREATE TABLE IF NOT EXISTS public.visit (
    id              uuid PRIMARY KEY,
    device_id       uuid NOT NULL,
    started_at      timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    landing_path    character varying(2048),
    referrer        character varying(2048),
    ip_address      character varying(45),
    geo             jsonb,
    user_agent      text,
    platform        character varying(20),
    screen          character varying(50),
    language        character varying(50),
    timezone        character varying(100),
    client_version  character varying(50),
    is_returning    boolean NOT NULL DEFAULT false,
    is_internal     boolean NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS idx_visit_started_at ON public.visit (started_at);
CREATE INDEX IF NOT EXISTS idx_visit_device_id ON public.visit (device_id);

ALTER TABLE public.visit OWNER TO postgres;

CREATE TABLE IF NOT EXISTS public.site_event (
    id          uuid PRIMARY KEY,
    visit_id    uuid NOT NULL REFERENCES public.visit(id),
    device_id   uuid NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    type        character varying(40) NOT NULL,
    path        character varying(2048),
    target_id   character varying(200),
    meta        jsonb,
    account_id  integer,
    is_admin    boolean NOT NULL DEFAULT false
);

CREATE INDEX IF NOT EXISTS idx_site_event_created_at ON public.site_event (created_at);
CREATE INDEX IF NOT EXISTS idx_site_event_type_created_at ON public.site_event (type, created_at);
CREATE INDEX IF NOT EXISTS idx_site_event_visit_id ON public.site_event (visit_id);
CREATE INDEX IF NOT EXISTS idx_site_event_device_id ON public.site_event (device_id);

ALTER TABLE public.site_event OWNER TO postgres;
